CREATE TABLE IF NOT EXISTS mad_v1_uploads (id TEXT PRIMARY KEY,owner TEXT NOT NULL DEFAULT 'owner',file_name TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes BETWEEN 1024 AND 83886080),sha256 TEXT NOT NULL CHECK(length(sha256)=64),chunk_count INTEGER NOT NULL CHECK(chunk_count BETWEEN 1 AND 20),chunks_received INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'uploading' CHECK(state IN ('uploading','complete')),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mad_v1_media_jobs (job_id TEXT PRIMARY KEY,upload_id TEXT NOT NULL REFERENCES mad_v1_uploads(id),prompt TEXT NOT NULL CHECK(length(prompt) BETWEEN 12 AND 600),rights_confirmed INTEGER NOT NULL CHECK(rights_confirmed=1),people_consent INTEGER NOT NULL CHECK(people_consent=1),external_ai_approved INTEGER NOT NULL CHECK(external_ai_approved=1),state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','claimed','review_ready','failed')),claim_id TEXT,claimed_at INTEGER,attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),result_bytes INTEGER,result_sha256 TEXT,result_chunks INTEGER,result_receipt TEXT,error_code TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS mad_v1_one_active_media_job ON mad_v1_media_jobs((1)) WHERE state IN ('queued','claimed');
CREATE INDEX IF NOT EXISTS mad_v1_media_job_order ON mad_v1_media_jobs(state,created_at);
